declare
  actor_id uuid;
  khe_tre_id uuid;
begin
  select id into actor_id from public.profiles where username = 'admin' limit 1;
  if actor_id is null then raise exception 'Chưa có tài khoản admin để gán người tạo dữ liệu'; end if;

