, HIS","responsibility":null,"sort_order":143},{"wbs":"XXIV","name":"THỦ TỤC SAU 10/12/2026","responsibility":null,"sort_order":148},{"wbs":"XXV","name":"KÝ HỢP ĐỒNG KCB BHYT","responsibility":null,"sort_order":152}]$groups$::jsonb)
